import{_ as a,o as s,c as t,a3 as n}from"./chunks/framework.BZCmpA0A.js";const k=JSON.parse('{"title":"02 · 開機流程","description":"","frontmatter":{},"headers":[],"relativePath":"topics/boot.md","filePath":"topics/boot.md","lastUpdated":1793510684000}'),r={name:"topics/boot.md"};function i(l,e,o,p,c,d){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="_02-·-開機流程" tabindex="-1">02 · 開機流程 <a class="header-anchor" href="#_02-·-開機流程" aria-label="Permalink to &quot;02 · 開機流程&quot;">​</a></h1><p>CPU 不認識 <code>entry.S</code> 或 <code>main.c</code> 這些檔名，只會執行記憶體中的機器指令。兩個來源檔最後會被連結到同一份核心映像。</p><h2 id="從韌體到-c" tabindex="-1">從韌體到 C <a class="header-anchor" href="#從韌體到-c" aria-label="Permalink to &quot;從韌體到 C&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>QEMU virt → OpenSBI → 0x80200000 的 _start</span></span>
<span class="line"><span>  → 設定 stack、清除 BSS → call kernel_main</span></span>
<span class="line"><span>  → FDT 裝置探測、頁表／檔案系統／圖形及輸入初始化</span></span>
<span class="line"><span>  → process_start → scheduler_loop → shell（UART）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>OpenSBI（RISC-V 韌體）完成早期準備，將控制權交給 S-mode（監督模式）核心。<code>kernel/linker.ld</code> 指定 <code>_start</code> 為入口，從 <code>0x80200000</code> 放置核心。</p><h2 id="entry-s-先準備-c-所需的環境" tabindex="-1">entry.S：先準備 C 所需的環境 <a class="header-anchor" href="#entry-s-先準備-c-所需的環境" aria-label="Permalink to &quot;entry.S：先準備 C 所需的環境&quot;">​</a></h2><p>原始碼：<a href="https://github.com/johnson931128/WUWAOS/blob/main/kernel/entry.S" target="_blank" rel="noreferrer">kernel/entry.S（GitHub）</a>。</p><p><code>la sp, __stack_top</code> 設定 sp（堆疊指標）。C 的函式呼叫與區域資料會用到堆疊，因此必須先準備它。</p><p><code>1:</code> 到 <code>2:</code> 的迴圈逐 byte 清除 BSS（未明確指定初值的靜態資料區）。例如 PCB 陣列與頁面管理欄位會從零開始。清除 B 個 bytes 的成本是 O(B)，不另外配置記憶體。</p><p><code>call kernel_main</code> 才是兩個檔案的接點：組合語言以函式呼叫進入 C。若 C 意外返回，後面的 WFI（等待中斷指令）迴圈阻止 CPU 繼續執行未知內容。</p><h2 id="main-c-把子系統串起來" tabindex="-1">main.c：把子系統串起來 <a class="header-anchor" href="#main-c-把子系統串起來" aria-label="Permalink to &quot;main.c：把子系統串起來&quot;">​</a></h2><p>原始碼：<a href="https://github.com/johnson931128/WUWAOS/blob/main/kernel/main.c" target="_blank" rel="noreferrer">kernel/main.c（GitHub）</a>。</p><p>先安裝 trap（陷阱／例外入口），再顯示 UART 動畫、探索 VirtIO 裝置、建立核心分頁映射與掛載檔案系統。若 FDT 找到 VirtIO GPU，核心建立 framebuffer 並畫出桌面；若另找到 VirtIO tablet，啟用游標更新。之後初始化 SBI 計時器、建立第一個行程並交給行程恢復流程；排程器輪詢輸入事件，同時保留 UART shell。</p><p><code>fdt</code> 指向 FDT（硬體裝置樹），是韌體交給核心的硬體描述資料。核心用它尋找 VirtIO 裝置，實體頁配置器也會保留它占用的記憶體。</p><h2 id="開機動畫與觀察" tabindex="-1">開機動畫與觀察 <a class="header-anchor" href="#開機動畫與觀察" aria-label="Permalink to &quot;開機動畫與觀察&quot;">​</a></h2><p><code>kernel/splash.c</code> 透過 UART 輸出 ANSI 終端控制碼，以圖案中點為中心逐欄揭露 WUWAOS。字形以 5×7 位元資料表示，再用背景色與空格組成 70 欄實心筆畫，從螢光黃綠漸變到薄荷綠；不依賴特殊字型。這時尚未進入使用者模式；動畫中的忙等不是排程器，也不代表已啟用計時器中斷。色塊版本見 <a href="./../SPEC-13-block-splash.html">Spec 13</a>。</p><p>執行 <code>make run</code>，應依序看到字樣、核心與裝置資訊、最後的 <code>wuwaos&gt;</code>。<code>/boot/kernel.elf</code> 是 WUFS 中的副本；目前真正啟動核心仍由 QEMU 的 <code>-kernel</code> 載入。</p><h2 id="virtio-圖形桌面" tabindex="-1">VirtIO 圖形桌面 <a class="header-anchor" href="#virtio-圖形桌面" aria-label="Permalink to &quot;VirtIO 圖形桌面&quot;">​</a></h2><p>QEMU 裝上 modern VirtIO GPU 與 tablet 後，kernel 以 FDT 找到裝置 MMIO 位址，不假設它們在固定 VirtIO slot。GPU 建立 B8G8R8X8 2D resource，掛上一段連續的 1280×720 framebuffer RAM，再設定 scanout 並提交像素；桌面是淡藍底和白色 <code>WUWAOS</code> 字樣。VirtIO tablet 提供絕對 X/Y 座標，核心依裝置範圍縮放、夾限到畫面內，於同步事件後更新游標。游標移動只重送舊位置與新位置覆蓋的矩形區域。</p><p>這是 kernel renderer（核心繪圖器），不是桌面伺服器或 user process；沒有視窗、工作列、圖形 shell、鍵盤操作或檔案管理器。沒有 GPU/tablet 時，原本的文字 shell 照常啟動。架構與實際驗收見 <a href="./../SPEC-28-native-desktop.html">Spec 28</a>。</p><p>WSLg/Linux 圖形工作階段可用 <code>make run-gui GUI_DISPLAY=gtk</code>（或 <code>sdl</code>）。Windows/WSL1 可分別在兩個 PowerShell 視窗啟動 VNC guest 與 TigerVNC viewer：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">wsl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d Ubuntu </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bash </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lc </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;cd /mnt/c/programing/WUWAOS &amp;&amp; make run-gui-vnc&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;C:\\path\\to\\vncviewer64.exe&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;127.0.0.1::5901&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>TigerVNC viewer 請從<a href="https://github.com/TigerVNC/tigervnc/releases" target="_blank" rel="noreferrer">官方 releases</a>安裝／下載。VNC server 和 QMP debug control 都綁定 localhost；<code>run-gui-vnc</code> 預設 VNC port 為 5901、QMP port 為 4451。圖形目標會像 <code>make run</code> 一樣先建立或更新磁碟映像；客體寫入會持續保留。QEMU 執行期間不要從主機端操作磁碟映像。VNC QEMU 使用 <code>-serial stdio</code>，在其 WSL 終端按 Ctrl+C 結束。</p><h2 id="延伸資料" tabindex="-1">延伸資料 <a class="header-anchor" href="#延伸資料" aria-label="Permalink to &quot;延伸資料&quot;">​</a></h2><p>觀念參考：<code>notes/ch2 Operating-System Structures.md</code> 的開機與核心結構。實作細節與早期動畫驗收見<a href="./../CODE_GUIDE.html">程式碼導覽</a>及 <a href="./../SPEC-04-boot-splash.html">Spec 04</a>。</p>`,25)])])}const b=a(r,[["render",i]]);export{k as __pageData,b as default};
